def _to_float(v):
    """Safely converts a value to float, returning 0.0 on failure.

    :param v: Value to convert to float.
    :type v: any
    :returns: Float value, or 0.0 if conversion fails.
    :rtype: float
    """
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0

def load_data(data_dir):
    """Loads model results, EF template, and pollutant flow CSVs from the given directory, returning them in a dict.

    :param data_dir: Directory containing model_results_multilocation.csv, EF_Template.csv, and optionally pollutant_flow.csv.
    :type data_dir: Path
    :returns: Dict with keys 'results' (DataFrame), 'ef' (DataFrame), 'pollutants' (DataFrame).
    :rtype: dict
    :raises FileNotFoundError: If model_results_multilocation.csv or EF_Template.csv are missing.
    """
    _a = {}
    _b = data_dir / 'model_results_multilocation.csv'
    if not _b.exists():
        raise FileNotFoundError(f'model_results_multilocation.csv not found in {data_dir}')
    _a['results'] = pd.read_csv(_b)
    _c = data_dir / 'EF_Template.csv'
    if not _c.exists():
        raise FileNotFoundError(f'EF_Template.csv not found in {data_dir}')
    _a['ef'] = pd.read_csv(_c)
    _e = [_d for _d in _a['ef'].columns if _d.startswith('EF_')]
    for _d in _e:
        _a['ef'][_d] = pd.to_numeric(_a['ef'][_d], errors='coerce').fillna(0.0)
    _f = data_dir / 'pollutant_flow.csv'
    if _f.exists():
        _a['pollutants'] = pd.read_csv(_f)
        print(f"  Loaded pollutant_flow.csv: {len(_a['pollutants']):,} rows")
    else:
        print(f'  WARNING: pollutant_flow.csv not found — Tab 4 will be empty')
        _a['pollutants'] = pd.DataFrame(columns=['analyzed_process', 'analyzed_process_location', 'flow_name', 'flow_category', 'flow_subcategory', 'flow_unit', 'flow_uuid', 'amount', 'num_contributing_activities'])
    return _a

def compute_lcia_by_process_location(results, ef):
    """Merges EF factors onto flow results and returns a DataFrame of per-(time period, process, location) LCIA impact totals for all EF columns.

    :param results: Model flow results with columns time_period, source, source_location, material, flow_value.
    :type results: pd.DataFrame
    :param ef: EF template with EF_ prefixed columns.
    :type ef: pd.DataFrame
    :returns: DataFrame with per-(time_period, source, source_location) sums for all EF columns.
    :rtype: pd.DataFrame
    """
    _b = [_a for _a in ef.columns if _a.startswith('EF_')]
    _c = results.merge(ef[['time_period', 'source', 'location', 'material'] + _b], left_on=['time_period', 'source', 'source_location', 'material'], right_on=['time_period', 'source', 'location', 'material'], how='left', suffixes=('', '_ef'))
    for _a in _b:
        _c[_a] = _c['flow_value'] * _c[_a].fillna(0.0)
    _d = _c.groupby(['time_period', 'source', 'source_location'])[_b].sum().reset_index()
    return _d

def compute_pollutant_by_process_location(results, pollutants):
    """Scales pollutant flow amounts by material flow volumes, returning a DataFrame of total pollutant amounts aggregated by time period, process, location, and pollutant name.

    :param results: Model flow results.
    :type results: pd.DataFrame
    :param pollutants: Pollutant flow data with columns analyzed_process, analyzed_process_location, flow_name, flow_unit, amount.
    :type pollutants: pd.DataFrame
    :returns: DataFrame of total pollutant amounts by time_period, source, source_location, flow_name, flow_unit; or empty DataFrame if no matches.
    :rtype: pd.DataFrame
    """
    if pollutants.empty:
        return pd.DataFrame()
    _a = []
    for (_b, _c) in results.iterrows():
        _d = _c['time_period']
        _e = _c['source']
        _f = _c['source_location']
        _g = _c['material']
        _h = _c['flow_value']
        _i = BLEECAM_TO_LCA.get((_e, _g), [])
        if not _i:
            continue
        _j = pollutants[pollutants['analyzed_process'].isin(_i) & (pollutants['analyzed_process_location'] == _f)]
        if _j.empty:
            continue
        _k = _j.groupby(['flow_name', 'flow_unit'])['amount'].mean().reset_index()
        for (_b, _l) in _k.iterrows():
            _a.append({'time_period': _d, 'source': _e, 'source_location': _f, 'flow_name': _l['flow_name'], 'flow_unit': _l['flow_unit'], 'total_amount': _h * _l['amount']})
    if not _a:
        return pd.DataFrame()
    _m = pd.DataFrame(_a)
    _n = _m.groupby(['time_period', 'source', 'source_location', 'flow_name', 'flow_unit'])['total_amount'].sum().reset_index()
    return _n

def build_json_datasets(results, lcia_agg, pollutant_agg, ef):
    """Assembles all data needed for the dashboard into JSON-serializable structures (time periods, locations, costs, LCIA, pollutants).

    :param results: Model flow results.
    :type results: pd.DataFrame
    :param lcia_agg: Aggregated LCIA impacts from compute_lcia_by_process_location.
    :type lcia_agg: pd.DataFrame
    :param pollutant_agg: Aggregated pollutant flows from compute_pollutant_by_process_location.
    :type pollutant_agg: pd.DataFrame
    :param ef: EF template DataFrame.
    :type ef: pd.DataFrame
    :returns: Dict of JSON-serializable datasets keyed by chart/tab name.
    :rtype: dict
    """
    _a = sorted(results['time_period'].unique().tolist())
    _b = sorted(set(results['source_location'].unique().tolist()))
    _c = sorted(results['source'].unique().tolist())
    _d = results.copy()
    _d['proc_cost_total'] = _d['flow_value'] * _d['process_cost'].fillna(0)
    _d['dom_trans_cost_total'] = _d['flow_value'] * _d['domestic_transport_cost'].fillna(0)
    _d['ship_cost_total'] = _d['flow_value'] * _d['shipping_cost'].fillna(0)
    _d['tariff_cost_total'] = _d['flow_value'] * _d['tariff_cost'].fillna(0)
    _e = _d.groupby(['time_period', 'source', 'source_location'])[['proc_cost_total', 'dom_trans_cost_total', 'ship_cost_total', 'tariff_cost_total', 'flow_value']].sum().reset_index()
    _f = {}
    for (_g, _h) in LCIA_METHODS.items():
        _f[_g] = {}
        for _i in _h['categories']:
            _j = f"{_h['prefix']}{_i}"
            if _j not in lcia_agg.columns:
                continue
            _k = []
            for (_l, _m) in lcia_agg.iterrows():
                _k.append({'t': int(_m['time_period']), 'src': _m['source'], 'loc': _m['source_location'], 'val': float(_m[_j])})
            _f[_g][_i] = _k
    _n = {}
    if not pollutant_agg.empty:
        _o = pollutant_agg.groupby(['flow_name', 'flow_unit'])['total_amount'].sum().reset_index().sort_values('total_amount', ascending=False)
        _p = _o.head(50).copy()
        _q = _o[_o['flow_name'].str.lower().str.contains('benz') & ~_o['flow_name'].isin(_p['flow_name'])]
        if not _q.empty:
            _p = pd.concat([_p, _q], ignore_index=True)
            print(f'  Added {len(_q)} benzene variant(s) to pollutant list')
        for (_l, _r) in _p.iterrows():
            _s = _r['flow_name']
            _t = _r['flow_unit']
            _u = f'{_s} [{_t}]'
            _v = pollutant_agg[pollutant_agg['flow_name'] == _s]
            _k = []
            for (_l, _m) in _v.iterrows():
                _k.append({'t': int(_m['time_period']), 'src': _m['source'], 'loc': _m['source_location'], 'val': float(_m['total_amount']), 'unit': _t})
            _n[_u] = _k
    _w = {'hp_magnet': '#8e44ad', 'neodynium dysprosium iron alloy': '#2c3e50', 'neodynium': '#1abc9c', 'dysprosium': '#e67e22', 'neodynium_oxide': '#16a085', 'dysprosium_oxide': '#d35400', 'phosphate': '#7f8c8d', 'flurocarbonate': '#bdc3c7', 'monazaite': '#95a5a6', 'bastnasite': '#a0522d', 'ion adsorption clay': '#c8a96e', 'iron': '#555555'}
    _x = []
    for _y in _a:
        _v = results[(results['time_period'] == _y) & (results['flow_value'] > 1e-06)].copy()
        if _v.empty:
            _x.append({'nodes': [], 'links': []})
            continue
        _v['src_node'] = _v['source'] + '||' + _v['source_location']
        _v['dst_node'] = _v['destination'] + '||' + _v['destination_location']
        _z = pd.unique(_v[['src_node', 'dst_node']].values.ravel())
        _ac = {_ab: _aa for (_aa, _ab) in enumerate(_z)}
        (_ad, _ae) = ([], [])
        for _ab in _z:
            _af = _ab.split('||')
            _ag = _af[0]
            _ah = _af[1] if len(_af) > 1 else ''
            _ad.append(f'{_ag}\n({_ah})' if _ah else _ag)
            _ae.append(LOC_COLOR.get(_ah, '#95a5a6'))
        (_ai, _aj, _ak, _al, _am) = ([], [], [], [], [])
        for (_l, _m) in _v.iterrows():
            _ai.append(_ac[_m['src_node']])
            _aj.append(_ac[_m['dst_node']])
            _ak.append(float(_m['flow_value']))
            _an = _w.get(_m['material'], '#aaaaaa')
            (_ao, _ap, _aq) = (int(_an[1:3], 16), int(_an[3:5], 16), int(_an[5:7], 16))
            _ar = _m['source_location'] != _m['destination_location']
            _as = '0.4' if _ar else '0.7'
            _al.append(f'rgba({_ao},{_ap},{_aq},{_as})')
            _am.append(f"{_m['material']}<br>{_m['source_location']}→{_m['destination_location']}<br>{_m['flow_value']:,.4f} kg")
        _x.append({'nodes': {'label': _ad, 'color': _ae, 'pad': 15, 'thickness': 20}, 'links': {'source': _ai, 'target': _aj, 'value': _ak, 'color': _al, 'label': _am}})
    _at = set()
    for _au in _b:
        for _av in _b:
            for _aw in ['sulfuric acid digestion', 'hydrochloric acid digestion', 'clay refining']:
                _at.add((_aw, _au, 'molten_salt electrolysis', _av, 'dysprosium_oxide'))
                _at.add((_aw, _au, 'metallothermic reduction', _av, 'neodynium_oxide'))
    _ax = results.copy()
    _ax['_unused'] = _ax.apply(lambda r: (_m['source'], _m['source_location'], _m['destination'], _m['destination_location'], _m['material']) in _at, axis=1)
    _ax['_cross'] = _ax['source_location'] != _ax['destination_location']
    _ax['_total_cost'] = (_ax.get('process_cost', pd.Series(0, index=_ax.index)).fillna(0) + _ax.get('domestic_transport_cost', pd.Series(0, index=_ax.index)).fillna(0) + _ax.get('shipping_cost', pd.Series(0, index=_ax.index)).fillna(0) + _ax.get('tariff_cost', pd.Series(0, index=_ax.index)).fillna(0)) * _ax['flow_value']

    def _loc_badge(loc):
        __a = LOC_COLOR.get(loc, '#aaa')
        return f'<span class="loc-badge" style="background:{__a}">{loc}</span>'
    _ay = ''
    for (_aa, (_l, _m)) in enumerate(_ax.iterrows()):
        cls = ('unused ' if _m['_unused'] else '') + ('cross' if _m['_cross'] else '') + (' alt' if _aa % 2 == 0 else '')
        _az = '<span class="badge bwarn">unused</span>' if _m['_unused'] else '<span class="badge bcross">cross-border</span>' if _m['_cross'] else ''
        _ba = f"{_m['process_cost']:.4f}" if pd.notna(_m.get('process_cost')) else '—'
        _bb = f"{_m['domestic_transport_cost']:.4f}" if pd.notna(_m.get('domestic_transport_cost')) else '—'
        _bc = f"{_m['shipping_cost']:.4f}" if pd.notna(_m.get('shipping_cost')) else '—'
        _bd = f"{_m['tariff_cost']:.4f}" if pd.notna(_m.get('tariff_cost')) else '—'
        ef = f"{_m['emission_factor']:.4f}" if pd.notna(_m.get('emission_factor')) else '—'
        _ay += f'<tr class="{cls.strip()}">' + f"<td>{_m['time_period']}</td>" + f"<td>{_m['source']}</td>" + f"<td>{_loc_badge(_m['source_location'])}</td>" + f"<td>{_m['destination']}</td>" + f"<td>{_loc_badge(_m['destination_location'])}</td>" + f"<td>{_m['material']}</td>" + f"<td>{_m['flow_value']:,.6f}</td>" + f'<td>{_ba}</td><td>{_bb}</td><td>{_bc}</td><td>{_bd}</td><td>{ef}</td>' + f'<td>{_az}</td></tr>\n'
    _be = _ax[_ax['_cross']].copy()
    _bf = ''
    if not _be.empty:
        _bg = _be.groupby(['time_period', 'source', 'source_location', 'destination', 'destination_location', 'material'])['flow_value'].sum().reset_index().sort_values(['time_period', 'source_location', 'destination_location'])
        for (_l, _m) in _bg.iterrows():
            _bf += f'<tr>' + f"<td>{int(_m['time_period'])}</td>" + f"<td>{_m['source']}</td>" + f"<td>{_loc_badge(_m['source_location'])}</td>" + f"<td>{_m['destination']}</td>" + f"<td>{_loc_badge(_m['destination_location'])}</td>" + f"<td>{_m['material']}</td>" + f"<td>{_m['flow_value']:,.4f}</td></tr>\n"
    return {'periods': _a, 'all_locs': _b, 'all_procs': _c, 'cost_data': _e.to_dict(orient='records'), 'lcia_data': _f, 'pollutant_data': _n, 'pollutant_flows': list(_n.keys()), 'sankey_frames': _x, 'loc_colors': LOC_COLOR, 'proc_colors': {_bh: PROCESS_COLOR[_aa % len(PROCESS_COLOR)] for (_aa, _bh) in enumerate(sorted(_c))}, 'lcia_methods': {_bi: list(_h['categories']) for (_bi, _h) in LCIA_METHODS.items()}, 'lcia_units': {'ReCiPe': {'Global Warming Potential (Gwp1000)': 'kg CO₂-eq', 'Fossil Fuel Potential (Ffp)': 'MJ-surplus', 'Freshwater Ecotoxicity Potential (Fetp)': 'kg 1,4-DCB-eq', 'Water Consumption Potential (Wcp)': 'm³'}, 'IMPACT World+': {'Climate change, short term, fossil': 'kg CO₂-eq', 'Water scarcity': 'm³ world-eq', 'Mineral resources use': 'MJ surplus', 'Fossil and nuclear energy use': 'MJ'}, 'TRACI2.1': {'Global Warming Potential (Gwp100)': 'kg CO₂-eq', 'Acidification Potential (Ap)': 'kg SO₂-eq'}}, 'all_rows_html': _ay, 'trade_rows_html': _bf}

def render_html(ds, obj_value, obj_name, ts, path):
    """Renders the full multi-tab dashboard HTML from the prebuilt JSON datasets and writes it to the given path.

    :param ds: JSON-serializable datasets from build_json_datasets.
    :type ds: dict
    :param obj_value: Solver objective value for the scenario.
    :type obj_value: float
    :param obj_name: Name of the minimized objective.
    :type obj_name: str
    :param ts: Timestamp string for the report header.
    :type ts: str
    :param path: Output file path.
    :type path: Path or str
    """
    _a = ds.pop('all_rows_html', '')
    _b = ds.pop('trade_rows_html', '')
    _c = ds['periods']
    _d = json.dumps(ds, ensure_ascii=False)
    _g = f"""<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<title>BLEECAM — Analytics Dashboard</title>\n<script src="https://cdn.plot.ly/plotly-2.27.0.min.js"></script>\n<style>\n:root {{\n  --navy:#1F3864; --amber:#856404; --amber-bg:#fff8e1; --amber-row:#fff3cd;\n  --green-bg:#e8f4e8; --alt-bg:#f7f7f7; --border:#ddd;\n  --cn:#e74c3c; --jp:#3498db; --au:#f39c12; --us:#27ae60;\n  --mm:#9b59b6; --my:#1abc9c; --ee:#34495e; --ca:#e67e22; --br:#16a085;\n}}\n*{{box-sizing:border-box;margin:0;padding:0}}\nbody{{font-family:'Segoe UI',Arial,sans-serif;font-size:13px;color:#222;background:#eef0f4}}\n/* ── Tab nav ── */\n.tab-nav{{display:flex;background:var(--navy);border-bottom:2px solid #e0e0e0;position:sticky;top:0;z-index:100;padding:0 24px}}\n.tab-btn{{padding:14px 22px;cursor:pointer;font-size:12px;font-weight:600;letter-spacing:.04em;color:rgba(255,255,255,.65);border:none;background:none;border-bottom:3px solid transparent;transition:all .2s}}\n.tab-btn:hover{{color:#fff}}\n.tab-btn.active{{color:#fff;border-bottom-color:#fff}}\n/* ── Header ── */\n.dash-header{{background:var(--navy);color:#fff;padding:18px 32px;display:flex;align-items:center;gap:20px}}\n.dash-header h1{{font-size:22px;font-weight:700}}\n.dash-header .meta{{font-size:12px;opacity:.75;margin-top:3px}}\n/* ── Tab content ── */\n.tab-content{{display:none;padding:0}}\n.tab-content.active{{display:block}}\n.container{{max-width:1500px;margin:24px auto;padding:0 20px}}\n/* ── Solver note ── */\n.solver-note{{background:#fff8e1;border:1px solid #e6a817;border-left:4px solid #e6a817;padding:12px 16px;border-radius:4px;margin-bottom:18px;font-size:12px;color:#5c3d00;line-height:1.7}}\n.solver-note strong{{color:var(--amber)}}\n/* ── Cards ── */\n.cards{{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:22px}}\n.card{{background:#fff;border-radius:10px;padding:16px 22px;flex:1 1 160px;\n       box-shadow:0 1px 5px rgba(0,0,0,.08);border-top:4px solid var(--navy)}}\n.card.warn{{border-top-color:#e6a817}}.card.info{{border-top-color:#3498db}}\n.card.cross{{border-top-color:#8e44ad}}\n.card h3{{font-size:10px;text-transform:uppercase;color:#999;letter-spacing:.06em}}\n.card .val{{font-size:24px;font-weight:700;color:var(--navy);margin-top:5px}}\n.card.warn .val{{color:var(--amber)}}.card.cross .val{{color:#8e44ad}}\n/* ── Sections ── */\n.section{{background:#fff;border-radius:10px;padding:22px 26px;margin-bottom:22px;\n          box-shadow:0 1px 5px rgba(0,0,0,.08)}}\n.section h2{{font-size:15px;color:var(--navy);border-bottom:2px solid var(--navy);\n             padding-bottom:8px;margin-bottom:16px;display:flex;align-items:center;gap:8px}}\n/* ── Controls ── */\n.ctrl-bar{{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px}}\n.ctrl-bar label{{font-size:12px;font-weight:600;color:var(--navy)}}\nselect{{padding:6px 8px;border:1px solid var(--border);border-radius:5px;font-size:12px;background:#fff;color:#222}}\nselect:focus{{outline:none;border-color:var(--navy)}}\ninput[type=text]{{padding:6px 10px;border:1px solid var(--border);border-radius:5px;font-size:12px;width:260px}}\n.mode-toggle{{display:flex;border:1px solid var(--navy);border-radius:5px;overflow:hidden}}\n.mode-btn{{padding:5px 14px;font-size:12px;cursor:pointer;background:#fff;color:var(--navy);border:none;transition:all .15s}}\n.mode-btn.active{{background:var(--navy);color:#fff;font-weight:600}}\n/* ── Country chips ── */\n.chip-group{{display:flex;flex-wrap:wrap;gap:5px;margin-bottom:10px}}\n.chip{{padding:3px 10px;border-radius:12px;font-size:11px;cursor:pointer;border:2px solid transparent;\n       font-weight:700;opacity:.45;transition:all .15s;color:#fff}}\n.chip.on{{opacity:1;box-shadow:0 1px 4px rgba(0,0,0,.25)}}\n/* ── Charts grid ── */\n.chart-grid{{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:22px}}\n@media(max-width:900px){{.chart-grid{{grid-template-columns:1fr}}}}\n.chart-box{{background:#fff;border-radius:10px;padding:18px 20px;\n            box-shadow:0 1px 5px rgba(0,0,0,.08)}}\n.chart-box h3{{font-size:12px;color:var(--navy);font-weight:600;margin-bottom:10px;\n               border-bottom:1px solid #eee;padding-bottom:6px}}\n/* ── Tables ── */\n.tbl-wrap{{overflow-x:auto}}\ntable{{border-collapse:collapse;width:100%;font-size:12px}}\nth{{background:var(--navy);color:#fff;padding:8px 10px;text-align:left;\n    position:sticky;top:0;white-space:nowrap}}\ntd{{padding:6px 10px;border-bottom:1px solid var(--border);vertical-align:middle}}\ntr.alt td{{background:var(--alt-bg)}}\ntr:hover td{{filter:brightness(.97)}}\n/* ── Badges ── */\n.badge{{display:inline-block;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:600}}\n.bwarn{{background:#fff3cd;color:var(--amber);border:1px solid #e6a817}}\n.bok{{background:var(--green-bg);color:#145214;border:1px solid #4caf50}}\n.loc-badge{{display:inline-block;padding:2px 7px;border-radius:4px;color:#fff;\n            font-size:11px;font-weight:700;letter-spacing:.04em}}\n.bcross{{background:#ede0ff;color:#6c3483;border:1px solid #8e44ad}}\ntr.cross td{{background:#f0e6ff}}\ntr.unused td{{background:var(--amber-row)}}\ntr.unused.cross td{{background:#ffe0cc}}\n/* ── Tbtn (toggle buttons) ── */\n.tbtn{{padding:5px 12px;border:1px solid var(--navy);border-radius:5px;\n       background:#fff;color:var(--navy);cursor:pointer;font-size:12px}}\n.tbtn.active{{background:var(--navy);color:#fff}}\n</style>\n</head>\n<body>\n\n<header class="dash-header">\n  <div>\n    <h1>🌐 BLEECAM — Supply Chain Analytics Dashboard</h1>\n    <p class="meta">Generated: {ts} &nbsp;|&nbsp; Objective: <strong>{obj_name}</strong>\n       &nbsp;|&nbsp; Value: <strong>{obj_value:,.2f}</strong> &nbsp;|&nbsp; Solver: IPOPT</p>\n  </div>\n</header>\n\n<nav class="tab-nav">\n  <button class="tab-btn active" onclick="switchTab('t1',this)">① Flow &amp; Sankey</button>\n  <button class="tab-btn"        onclick="switchTab('t2',this)">② Cost Breakdown</button>\n  <button class="tab-btn"        onclick="switchTab('t3',this)">③ LCIA Emissions</button>\n  <button class="tab-btn"        onclick="switchTab('t4',this)">④ Pollutant Inventory</button>\n</nav>\n\n<!-- ══════════════════════════════════════════════════════════════════\n     TAB 1 — FLOW & SANKEY\n══════════════════════════════════════════════════════════════════ -->\n<div id="t1" class="tab-content active"><div class="container">\n\n  <div class="solver-note">\n    <strong>ℹ Solver objective note:</strong> This model was solved minimising\n    <strong>{obj_name}</strong>. The emissions and LCIA results shown in Tabs 3 and 4\n    are <em>post-hoc</em> — they report the environmental impact of the cost-optimal\n    solution, not an emissions-minimised solution. To minimise emissions,\n    uncomment <code>total_emissions_rule</code> in REE.py and re-solve.\n  </div>\n\n  <div class="section">\n    <h2>Material Flow Sankey</h2>\n    <div class="ctrl-bar">\n      <label>Period:</label>\n      <select id="sankeyPeriod" onchange="renderSankey()"></select>\n      <span style="font-size:11px;color:var(--text2)">Node = location colour &nbsp;|&nbsp; Link = material &nbsp;|&nbsp; Semi-transparent = cross-border</span>\n    </div>\n    <div id="sankey" style="height:560px"></div>\n  </div>\n\n  <div class="section">\n    <h2>Cross-Border Trade Volumes</h2>\n    <div class="ctrl-bar">\n      <label>Period:</label>\n      <select id="barPeriod" onchange="renderBar()"></select>\n    </div>\n    <div class="chart-grid">\n      <div class="chart-box"><h3>Volume by Arc (this period)</h3><div id="barChart" style="height:320px"></div></div>\n      <div class="chart-box"><h3>Volume Over Time by Source Country</h3><div id="lineChart" style="height:320px"></div></div>\n    </div>\n  </div>\n\n\n<!-- ── Trade Arc Table ── -->\n<div class="section">\n  <h2>✈️ Cross-Border Trade Flows</h2>\n  <div class="filter-bar">\n    <input type="text" id="tradeFilter" placeholder="Filter source, destination, material…" oninput="filterTrade()">\n    <select id="tradeLocFrom" onchange="filterTrade()">\n      <option value="">All source locations</option>\n      {''.join((f'<option value="{_e}">{_e}</option>' for _e in ['CN', 'JP', 'AU', 'US', 'MM', 'MY', 'EE', 'CA', 'BR']))}\n    </select>\n    <select id="tradeLocTo" onchange="filterTrade()">\n      <option value="">All dest locations</option>\n      {''.join((f'<option value="{_e}">{_e}</option>' for _e in ['CN', 'JP', 'AU', 'US', 'MM', 'MY', 'EE', 'CA', 'BR']))}\n    </select>\n    <select id="tradePeriod" onchange="filterTrade()">\n      <option value="">All periods</option>\n      {''.join((f'<option value="{_f}">Period {_f}</option>' for _f in _c))}\n    </select>\n  </div>\n  <div class="tbl-wrap">\n  <table id="tradeTable">\n    <thead><tr>\n      <th>Period</th><th>Source Process</th><th>From</th>\n      <th>Dest Process</th><th>To</th><th>Material</th><th>Volume (kg)</th>\n    </tr></thead>\n    <tbody>{_b}</tbody>\n  </table>\n  </div>\n</div>\n\n<!-- ── All Flows ── -->\n<div class="section">\n  <h2>📋 All Material Flows</h2>\n  <div class="filter-bar">\n    <input type="text" id="flowFilter" placeholder="Filter source, destination, material…" oninput="filterFlows()">\n    <select id="flowPeriod" onchange="filterFlows()">\n      <option value="">All periods</option>\n      {''.join((f'<option value="{_f}">Period {_f}</option>' for _f in _c))}\n    </select>\n    <select id="flowLoc" onchange="filterFlows()">\n      <option value="">All locations</option>\n      {''.join((f'<option value="{_e}">{_e}</option>' for _e in ['CN', 'JP', 'AU', 'US', 'MM', 'MY', 'EE', 'CA', 'BR']))}\n    </select>\n    <button class="tbtn active" id="btnAll"    onclick="setFlowFilter('all')">All</button>\n    <button class="tbtn"        id="btnActive" onclick="setFlowFilter('active')">Active only</button>\n    <button class="tbtn"        id="btnCross"  onclick="setFlowFilter('cross')">Cross-border</button>\n    <button class="tbtn"        id="btnUnused" onclick="setFlowFilter('unused')">Unused only</button>\n  </div>\n  <div class="tbl-wrap">\n  <table id="flowTable">\n    <thead><tr>\n      <th>Period</th><th>Source</th><th>From</th><th>Destination</th><th>To</th>\n      <th>Material</th><th>Volume (kg)</th>\n      <th>Proc Cost ($/kg)</th><th>Dom. Transport ($/kg)</th><th>Intl. Shipping ($/kg)</th><th>Tariff ($/kg)</th>\n      <th>EF (GWP)</th><th>Type</th>\n    </tr></thead>\n    <tbody>{_a}</tbody>\n  </table>\n  </div>\n</div>\n\n</div></div><!-- /container t1 -->\n\n<!-- ══════════════════════════════════════════════════════════════════\n     TAB 2 — COST BREAKDOWN\n══════════════════════════════════════════════════════════════════ -->\n<div id="t2" class="tab-content"><div class="container">\n\n  <div class="section">\n    <h2>Cost Controls</h2>\n    <div class="ctrl-bar">\n      <label>View:</label>\n      <div class="mode-toggle">\n        <button class="mode-btn active" id="c-snap-btn" onclick="setCostMode('snapshot')">Snapshot</button>\n        <button class="mode-btn"        id="c-time-btn" onclick="setCostMode('timeseries')">Time Series</button>\n      </div>\n      <label>Period:</label>\n      <select id="costPeriod" onchange="renderCost()"></select>\n      <label>Group by:</label>\n      <select id="costGroup" onchange="renderCost()">\n        <option value="process">Process</option>\n        <option value="country">Country</option>\n      </select>\n    </div>\n    <div class="ctrl-bar">\n      <label>Countries:</label>\n      <div class="chip-group" id="costChips"></div>\n    </div>\n  </div>\n\n  <div class="chart-grid">\n    <div class="chart-box"><h3>Processing Cost ($)</h3>  <div id="c-proc"  style="height:380px"></div></div>\n    <div class="chart-box"><h3>Dom. Transport Cost ($)</h3> <div id="c-trans" style="height:380px"></div></div>\n    <div class="chart-box"><h3>Intl. Shipping Cost ($)</h3>  <div id="c-ship"  style="height:380px"></div></div>\n    <div class="chart-box"><h3>Tariff Cost ($)</h3>      <div id="c-tariff" style="height:380px"></div></div>\n    <div class="chart-box"><h3>Total Cost — Stacked ($)</h3><div id="c-total" style="height:380px"></div></div>\n    <div class="chart-box"><h3>Total Cost by Process &amp; Country ($)</h3><div id="c-stack" style="height:380px"></div></div>\n  </div>\n\n</div></div><!-- /container t2 -->\n\n<!-- ══════════════════════════════════════════════════════════════════\n     TAB 3 — LCIA EMISSIONS\n══════════════════════════════════════════════════════════════════ -->\n<div id="t3" class="tab-content">\n\n  <div class="solver-note">\n    <strong>ℹ Post-hoc reporting:</strong> Values shown = Σ (flow quantity [kg] × emission factor [impact/kg])\n    for the cost-optimal solution. All three LCIA methods share the same underlying\n    ecoinvent 2020 SSP2-Base inventory; differences reflect characterisation choices.\n    <strong>EF_weighted GWP</strong> = ReCiPe GWP1000 (they are identical — the weighted column\n    is a backward-compatibility alias written by lcia_pipeline_full.py).\n  </div>\n\n  <div class="section">\n    <h2>LCIA Controls</h2>\n    <div class="ctrl-bar">\n      <label>View:</label>\n      <div class="mode-toggle">\n        <button class="mode-btn active" id="l-snap-btn" onclick="setLciaMode('snapshot')">Snapshot</button>\n        <button class="mode-btn"        id="l-time-btn" onclick="setLciaMode('timeseries')">Time Series</button>\n      </div>\n      <label>Period:</label>\n      <select id="lciaPeriod" onchange="renderLcia()"></select>\n      <label>Method:</label>\n      <select id="lciaMethod" onchange="updateLciaCategories()"></select>\n      <label>Category:</label>\n      <select id="lciaCategory" onchange="renderLcia()" style="min-width:320px"></select>\n    </div>\n    <div class="ctrl-bar">\n      <label>Countries:</label>\n      <div class="chip-group" id="lciaChips"></div>\n    </div>\n  </div>\n\n  <div class="chart-grid">\n    <div class="chart-box"><h3>Impact by Process</h3>   <div id="l-proc"    style="height:400px"></div></div>\n    <div class="chart-box"><h3>Impact by Country</h3>   <div id="l-country" style="height:400px"></div></div>\n    <div class="chart-box"><h3>Process Share (%)</h3>   <div id="l-pie"     style="height:400px"></div></div>\n    <div class="chart-box"><h3>Impact by Process &amp; Country (stacked)</h3><div id="l-heat"    style="height:400px"></div></div>\n  </div>\n\n</div></div><!-- /container t3 -->\n\n<!-- ══════════════════════════════════════════════════════════════════\n     TAB 4 — POLLUTANT INVENTORY\n══════════════════════════════════════════════════════════════════ -->\n<div id="t4" class="tab-content"><div class="container">\n\n  <div class="section">\n    <h2>Pollutant Controls</h2>\n    <div class="ctrl-bar">\n      <label>View:</label>\n      <div class="mode-toggle">\n        <button class="mode-btn active" id="p-snap-btn" onclick="setPollMode('snapshot')">Snapshot</button>\n        <button class="mode-btn"        id="p-time-btn" onclick="setPollMode('timeseries')">Time Series</button>\n      </div>\n      <label>Period:</label>\n      <select id="pollPeriod" onchange="renderPoll()"></select>\n      <label>Show top:</label>\n      <select id="pollTopN" onchange="renderPoll()">\n        <option value="10">Top 10</option><option value="20">Top 20</option><option value="50">Top 50</option>\n      </select>\n    </div>\n    <div class="flow-filter">\n      <input type="text" id="pollSearch" placeholder="Filter pollutant name…" oninput="renderPoll()">\n      <select id="pollFlow" onchange="renderPoll()" style="min-width:340px"><option value="">— all substances —</option></select>\n    </div>\n    <div class="ctrl-bar">\n      <label>Countries:</label>\n      <div class="chip-group" id="pollChips"></div>\n    </div>\n  </div>\n\n  <div class="chart-grid">\n    <div class="chart-box"><h3>Total Mass by Substance</h3><div id="p-bar"     style="height:420px"></div></div>\n    <div class="chart-box"><h3>Mass by Process</h3>        <div id="p-proc"    style="height:420px"></div></div>\n    <div class="chart-box"><h3>Mass by Country</h3>        <div id="p-country" style="height:420px"></div></div>\n    <div class="chart-box"><h3>Selected Substance Over Time</h3><div id="p-time"    style="height:420px"></div></div>\n  </div>\n\n</div></div><!-- /container t4 -->\n\n<!-- ══════════════════════════════════════════════════════════════════\n     DATA + JAVASCRIPT\n══════════════════════════════════════════════════════════════════ -->\n<script>\nconst D = {_d};\n\nconst PERIODS    = D.periods;\nconst ALL_LOCS   = D.all_locs;\nconst ALL_PROCS  = D.all_procs;\nconst LOC_COLORS = D.loc_colors;\nconst PROC_COLORS= D.proc_colors;\nconst PROCESS_COLOR = ALL_PROCS.map(function(p) {{ return PROC_COLORS[p] || '#95a5a6'; }});\nconst PLOTLY_CONF= {{responsive:true, displayModeBar:false}};\n\nconst PLOT_LAYOUT = (extra) => Object.assign({{\n  paper_bgcolor:'transparent', plot_bgcolor:'transparent',\n  font:{{family:'Segoe UI,Arial,sans-serif', size:11, color:'#333'}},\n  margin:{{l:60,r:20,t:30,b:60}},\n  legend:{{orientation:'h', y:-0.2, font:{{size:10}}}},\n  xaxis:{{gridcolor:'#e8ecf0', zerolinecolor:'#e8ecf0'}},\n  yaxis:{{gridcolor:'#e8ecf0', zerolinecolor:'#e8ecf0'}},\n}}, extra||{{}});\n\n// ── State ─────────────────────────────────────────────────────────────────────\nlet costMode = 'snapshot';\nlet lciaMode = 'snapshot';\nlet pollMode = 'snapshot';\n// Per-tab active location state (independent selections)\nconst tabLocs = {{\n  costChips: {{}},\n  lciaChips: {{}},\n  pollChips: {{}}\n}};\nALL_LOCS.forEach(l => {{\n  tabLocs.costChips[l] = true;\n  tabLocs.lciaChips[l] = true;\n  tabLocs.pollChips[l] = true;\n}});\n\n// ── Init ──────────────────────────────────────────────────────────────────────\ndocument.addEventListener('DOMContentLoaded', function() {{\n  // Populate period selects\n  ['sankeyPeriod','barPeriod','costPeriod','lciaPeriod','pollPeriod'].forEach(id => {{\n    const sel = document.getElementById(id);\n    PERIODS.forEach(t => {{\n      const o = document.createElement('option');\n      o.value = t; o.textContent = 'Period ' + t;\n      sel.appendChild(o);\n    }});\n  }});\n\n  // Country chips (shared across tabs)\n  ['costChips','lciaChips','pollChips'].forEach(gid => {{\n    const g = document.getElementById(gid);\n    ALL_LOCS.forEach(loc => {{\n      const c = document.createElement('span');\n      c.className = 'chip on';\n      c.textContent = loc;\n      c.style.background = LOC_COLORS[loc] || '#555';\n      c.dataset.loc = loc;\n      c.dataset.group = gid;\n      c.onclick = () => toggleChip(c, gid);\n      g.appendChild(c);\n    }});\n  }});\n\n  // LCIA method/category selects\n  const mSel = document.getElementById('lciaMethod');\n  Object.keys(D.lcia_methods).forEach(m => {{\n    const o = document.createElement('option'); o.value = m; o.textContent = m; mSel.appendChild(o);\n  }});\n  updateLciaCategories();\n\n  // Pollutant flow select\n  const pfSel = document.getElementById('pollFlow');\n  D.pollutant_flows.forEach(f => {{\n    const o = document.createElement('option'); o.value = f; o.textContent = f; pfSel.appendChild(o);\n  }});\n\n  renderSankey(); renderBar();\n  renderCost(); renderLcia(); renderPoll();\n}});\n\n// ── Tab switching ─────────────────────────────────────────────────────────────\nfunction switchTab(id, btn) {{\n  document.querySelectorAll('.tab-content').forEach(el => el.classList.remove('active'));\n  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n  document.getElementById(id).classList.add('active');\n  btn.classList.add('active');\n  // Trigger redraws on activation\n  if (id==='t1') {{ renderSankey(); renderBar(); }}\n  if (id==='t2') renderCost();\n  if (id==='t3') renderLcia();\n  if (id==='t4') renderPoll();\n}}\n\n// ── Country chip toggle ───────────────────────────────────────────────────────\nfunction toggleChip(chip, group) {{\n  const loc = chip.dataset.loc;\n  const sameGroup = document.querySelectorAll(`[data-group="${{group}}"].on`);\n  if (chip.classList.contains('on') && sameGroup.length <= 1) return; // keep at least 1\n  chip.classList.toggle('on');\n  tabLocs[group][loc] = chip.classList.contains('on');\n  if (group === 'costChips') renderCost();\n  if (group === 'lciaChips') renderLcia();\n  if (group === 'pollChips') renderPoll();\n}}\n\nfunction getActiveLocs(group) {{ return ALL_LOCS.filter(l => tabLocs[group][l]); }}\n\n// ── HELPERS ───────────────────────────────────────────────────────────────────\nfunction getVal(row, key) {{ return typeof row[key] === 'number' ? row[key] : 0; }}\n\nfunction filteredCostData(period, locs) {{\n  return D.cost_data.filter(r =>\n    (period === null || r.time_period === period) && locs.includes(r.source_location)\n  );\n}}\n\nfunction filteredLciaRows(method, category, period, locs) {{\n  const rows = (D.lcia_data[method] || {{}})[category] || [];\n  return rows.filter(r => (period === null || r.t === period) && locs.includes(r.loc));\n}}\n\nfunction filteredPollRows(flowKey, period, locs) {{\n  const rows = (D.pollutant_data[flowKey]) || [];\n  return rows.filter(r => (period === null || r.t === period) && locs.includes(r.loc));\n}}\n\nconst DARK = {{\n  paper_bgcolor:'#ffffff', plot_bgcolor:'#f7f9fc',\n  font:{{family:'Segoe UI,Arial,sans-serif',size:11,color:'#333'}},\n  margin:{{l:60,r:16,t:32,b:70}},\n  xaxis:{{gridcolor:'#e8ecf0',zerolinecolor:'#e8ecf0',tickfont:{{size:10,color:'#555'}}}},\n  yaxis:{{gridcolor:'#e8ecf0',zerolinecolor:'#e8ecf0',tickfont:{{size:10,color:'#555'}}}},\n  legend:{{orientation:'h',y:-0.28,font:{{size:10,color:'#555'}}}},\n}};\n\n// ── TAB 1: SANKEY ─────────────────────────────────────────────────────────────\nfunction renderSankey() {{\n  const t   = parseInt(document.getElementById('sankeyPeriod').value);\n  const idx = PERIODS.indexOf(t);\n  const f   = D.sankey_frames[idx];\n  if (!f || !f.nodes || f.nodes.label.length === 0) {{\n    Plotly.purge('sankey');\n    document.getElementById('sankey').innerHTML = '<p style="text-align:center;color:#999;padding:40px">No flows in this period.</p>';\n    return;\n  }}\n  Plotly.react('sankey', [{{\n    type:'sankey', orientation:'h', arrangement:'snap',\n    node:{{label:f.nodes.label, color:f.nodes.color, pad:f.nodes.pad, thickness:f.nodes.thickness, line:{{color:'#ffffff',width:.5}}}},\n    link:{{source:f.links.source, target:f.links.target, value:f.links.value, color:f.links.color, label:f.links.label, hovertemplate:'%{{label}}<extra></extra>'}}\n  }}], {{\n    font:{{size:11,family:'Segoe UI,Arial,sans-serif',color:'#222'}},\n    paper_bgcolor:'#ffffff', margin:{{l:10,r:10,t:10,b:10}}\n  }}, PLOTLY_CONF);\n}}\n\n// ── TAB 1: BAR + LINE ────────────────────────────────────────────────────────\nfunction renderBar() {{\n  const t = parseInt(document.getElementById('barPeriod').value);\n  // Cross-border volumes by arc\n  const crossRows = D.cost_data.filter(r => r.time_period === t);\n  // group by source_location\n  const arcVol = {{}};\n  // Actually use sankey frames for cross-border detection — simpler approach:\n  // just show flow_value total per source country for this period\n  const byLoc = {{}};\n  D.cost_data.filter(r => r.time_period === t).forEach(r => {{\n    byLoc[r.source_location] = (byLoc[r.source_location]||0) + r.flow_value;\n  }});\n  const labels = Object.keys(byLoc);\n  const vals   = labels.map(l => byLoc[l]);\n  Plotly.react('barChart', [{{\n    type:'bar', x:labels, y:vals,\n    marker:{{color:labels.map(l => LOC_COLORS[l]||'#aaa'), opacity:.85}},\n    text:vals.map(v=>v.toFixed(2)+' kg'), textposition:'outside',\n    hovertemplate:'%{{x}}: %{{y:,.3f}} kg<extra></extra>'\n  }}], Object.assign({{}},DARK,{{title:{{text:'Flow Volume by Source Country — Period '+t,font:{{size:12,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n  // Time series: flow volume per source location over time\n  const traces = ALL_LOCS.map(loc => {{\n    const ys = PERIODS.map(tp => {{\n      return D.cost_data.filter(r => r.time_period===tp && r.source_location===loc)\n                        .reduce((s,r)=>s+r.flow_value,0);\n    }});\n    return {{type:'scatter',mode:'lines+markers',name:loc,x:PERIODS,y:ys,\n             line:{{color:LOC_COLORS[loc]||'#aaa',width:2}},marker:{{size:5}},\n             hovertemplate:'Period %{{x}}: %{{y:,.3f}} kg<extra>'+loc+'</extra>'}};\n  }}).filter(tr=>tr.y.some(v=>v>0));\n  Plotly.react('lineChart', traces,\n    Object.assign({{}},DARK,{{title:{{text:'Total Flow Volume Over Time',font:{{size:12,color:'#1F3864'}}}}}}),\n    PLOTLY_CONF);\n}}\n\n// ── TAB 2: COST ───────────────────────────────────────────────────────────────\nfunction setCostMode(m) {{\n  costMode = m;\n  document.getElementById('c-snap-btn').classList.toggle('active', m==='snapshot');\n  document.getElementById('c-time-btn').classList.toggle('active', m==='timeseries');\n  document.getElementById('costPeriod').disabled = (m==='timeseries');\n  renderCost();\n}}\n\nfunction renderCost() {{\n  const locs   = getActiveLocs('costChips');\n  const period = costMode==='snapshot' ? parseInt(document.getElementById('costPeriod').value) : null;\n  const groupBy= document.getElementById('costGroup').value;\n\n  const costFields = ['proc_cost_total','dom_trans_cost_total','ship_cost_total','tariff_cost_total'];\n  const costLabels = ['Processing','Dom. Transport','Intl. Shipping','Tariff'];\n  const costCols   = ['#00c896','#f5a623','#3498db','#e74c3c'];\n\n  if (costMode === 'snapshot') {{\n    const rows = filteredCostData(period, locs);\n    const dim  = groupBy === 'process' ? 'source' : 'source_location';\n    const keys = [...new Set(rows.map(r=>r[dim]))].sort();\n\n    ['c-proc','c-trans','c-ship','c-tariff'].forEach((divId, fi) => {{\n      const field = costFields[fi];\n      const agg = {{}};\n      rows.forEach(r => {{ agg[r[dim]] = (agg[r[dim]]||0) + (r[field]||0); }});\n      const x = keys, y = keys.map(k=>agg[k]||0);\n      const colors = groupBy==='country' ? x.map(l=>LOC_COLORS[l]||'#aaa') : x.map((_,i)=>PROCESS_COLOR[i%PROCESS_COLOR.length]);\n      Plotly.react(divId, [{{type:'bar',x,y,marker:{{color:colors,opacity:.85}},\n        hovertemplate:'%{{x}}: $%{{y:,.2f}}<extra></extra>'}}],\n        Object.assign({{}},DARK,{{title:{{text:costLabels[fi]+' Cost by BLEECAM Process ($)',font:{{size:12,color:'#1F3864'}}}}}}),\n        PLOTLY_CONF);\n    }});\n\n    // Stacked total\n    const stackTraces = costFields.map((field,fi) => {{\n      const agg = {{}};\n      rows.forEach(r => {{ agg[r[dim]] = (agg[r[dim]]||0) + (r[field]||0); }});\n      return {{type:'bar',name:costLabels[fi],x:keys,y:keys.map(k=>agg[k]||0),\n               marker:{{color:costCols[fi]}},hovertemplate:'%{{x}}<br>%{{y:,.2f}}<extra>'+costLabels[fi]+'</extra>'}};\n    }});\n    Plotly.react('c-total', stackTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',title:{{text:'Total Cost — Stacked ($)',font:{{size:12,color:'#1F3864'}}}}}}),\n      PLOTLY_CONF);\n\n    // Process × country stacked bar — processes on x-axis, stacked by country\n    const procKeys = [...new Set(rows.map(r=>r.source))].sort();\n    const totalCostFn = r => (r.proc_cost_total||0)+(r.dom_trans_cost_total||0)+(r.ship_cost_total||0)+(r.tariff_cost_total||0);\n    const cstackTraces = locs.map(loc => {{\n      const ys = procKeys.map(proc =>\n        rows.filter(r=>r.source===proc&&r.source_location===loc)\n            .reduce((s,r)=>s+totalCostFn(r),0));\n      return {{type:'bar',name:loc,x:procKeys,y:ys,\n               marker:{{color:LOC_COLORS[loc]||'#aaa'}},\n               hovertemplate:'%{{x}}: $%{{y:,.2f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('c-stack', cstackTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',\n        title:{{text:'Total Cost by Process & Country ($)',font:{{size:12,color:'#1F3864'}}}},\n        xaxis:Object.assign({{}},DARK.xaxis,{{tickangle:-35}})}})\n      , PLOTLY_CONF);\n\n  }} else {{\n    // Time-series: one trace per country or process\n    const dim = groupBy==='process' ? 'source' : 'source_location';\n    const allRows = filteredCostData(null, getActiveLocs('costChips'));\n    const dimKeys = [...new Set(allRows.map(r=>r[dim]))].sort();\n    const totalField = r => (r.proc_cost_total||0)+(r.dom_trans_cost_total||0)+(r.ship_cost_total||0)+(r.tariff_cost_total||0);\n\n    const plotDivs = ['c-proc','c-trans','c-ship','c-tariff','c-total'];\n    const fields   = [...costFields, 'total'];\n\n    plotDivs.forEach((divId, fi) => {{\n      const field = fields[fi];\n      const traces = dimKeys.map((k,ki) => {{\n        const ys = PERIODS.map(tp => {{\n          return allRows.filter(r=>r.time_period===tp && r[dim]===k)\n                        .reduce((s,r)=>s+(field==='total'?totalField(r):(r[field]||0)),0);\n        }});\n        const col = groupBy==='country' ? (LOC_COLORS[k]||'#aaa') : PROCESS_COLOR[ki%PROCESS_COLOR.length];\n        return {{type:'scatter',mode:'lines+markers',name:k,x:PERIODS,y:ys,\n                 line:{{color:col,width:2}},marker:{{size:5}},\n                 hovertemplate:'Period %{{x}}: $%{{y:,.2f}}<extra>'+k+'</extra>'}};\n      }}).filter(tr=>tr.y.some(v=>v>0));\n      const titles = [...costLabels,'Total'];\n      Plotly.react(divId, traces,\n        Object.assign({{}},DARK,{{title:{{text:titles[fi]+' Cost Over Time ($)',font:{{size:12,color:'#1F3864'}}}}}}),\n        PLOTLY_CONF);\n    }});\n\n    // Process × country stacked bar — cumulative across all periods\n    const cstackProcs = [...new Set(allRows.map(r=>r.source))].sort();\n    const cstackTsTraces = getActiveLocs('costChips').map(loc => {{\n      const ys = cstackProcs.map(proc =>\n        allRows.filter(r=>r.source===proc&&r.source_location===loc)\n               .reduce((s,r)=>s+totalField(r),0));\n      return {{type:'bar',name:loc,x:cstackProcs,y:ys,\n               marker:{{color:LOC_COLORS[loc]||'#aaa'}},\n               hovertemplate:'%{{x}}: $%{{y:,.2f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('c-stack', cstackTsTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',\n        title:{{text:'Total Cost by Process & Country (cumulative)',font:{{size:12,color:'#1F3864'}}}},\n        xaxis:Object.assign({{}},DARK.xaxis,{{tickangle:-35}})}})\n      , PLOTLY_CONF);\n  }}\n}}\n\n// ── TAB 3: LCIA ───────────────────────────────────────────────────────────────\nfunction updateLciaCategories() {{\n  const method = document.getElementById('lciaMethod').value;\n  const sel    = document.getElementById('lciaCategory');\n  sel.innerHTML = '';\n  (D.lcia_methods[method]||[]).forEach(cat => {{\n    const o = document.createElement('option'); o.value = cat; o.textContent = cat; sel.appendChild(o);\n  }});\n  renderLcia();\n}}\n\nfunction setLciaMode(m) {{\n  lciaMode = m;\n  document.getElementById('l-snap-btn').classList.toggle('active', m==='snapshot');\n  document.getElementById('l-time-btn').classList.toggle('active', m==='timeseries');\n  document.getElementById('lciaPeriod').disabled = (m==='timeseries');\n  renderLcia();\n}}\n\nfunction renderLcia() {{\n  const locs   = getActiveLocs('lciaChips');\n  const method = document.getElementById('lciaMethod').value;\n  const cat    = document.getElementById('lciaCategory').value;\n  const period = lciaMode==='snapshot' ? parseInt(document.getElementById('lciaPeriod').value) : null;\n\n  if (lciaMode === 'snapshot') {{\n    const rows = filteredLciaRows(method, cat, period, locs);\n\n    // By process\n    const byProc = {{}};\n    rows.forEach(r => {{ byProc[r.src] = (byProc[r.src]||0)+r.val; }});\n    const pKeys = Object.keys(byProc).sort();\n    Plotly.react('l-proc', [{{type:'bar',x:pKeys,y:pKeys.map(k=>byProc[k]),\n      marker:{{color:pKeys.map((_,i)=>PROCESS_COLOR[i%PROCESS_COLOR.length]),opacity:.85}},\n      hovertemplate:'%{{x}}: %{{y:,.4f}}<extra></extra>'}}],\n      Object.assign({{}},DARK,{{title:{{text:cat+' by Supply Chain Process',font:{{size:11,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // By country — stacked by process\n    const stackTraces = pKeys.map((proc,pi) => {{\n      const ys = locs.map(loc => rows.filter(r=>r.src===proc&&r.loc===loc).reduce((s,r)=>s+r.val,0));\n      return {{type:'bar',name:proc,x:locs,y:ys,marker:{{color:PROCESS_COLOR[pi%PROCESS_COLOR.length]}},\n               hovertemplate:'%{{x}}<br>%{{y:,.4f}}<extra>'+proc+'</extra>'}};\n    }});\n    Plotly.react('l-country', stackTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',title:{{text:cat+' by Country',font:{{size:11,color:'#1F3864'}}}}}}),\n      PLOTLY_CONF);\n\n    // Pie — process share\n    const total = Object.values(byProc).reduce((a,b)=>a+b,0);\n    Plotly.react('l-pie', [{{type:'pie',labels:pKeys,values:pKeys.map(k=>byProc[k]),\n      marker:{{colors:pKeys.map((_,i)=>PROCESS_COLOR[i%PROCESS_COLOR.length])}},\n      textinfo:'label+percent', hovertemplate:'%{{label}}: %{{value:,.4f}}<extra></extra>',\n      hole:.35}}],\n      {{paper_bgcolor:'#ffffff',plot_bgcolor:'#ffffff',font:{{family:'Segoe UI,Arial,sans-serif',size:11,color:'#333'}},\n        margin:{{l:10,r:10,t:28,b:10}}}}, PLOTLY_CONF);\n\n    // Stacked bar — x = process, stacked by country\n    const heatTraces = locs.map(loc => {{\n      const ys = pKeys.map(proc => rows.filter(r=>r.src===proc&&r.loc===loc).reduce((s,r)=>s+r.val,0));\n      return {{type:'bar', name:loc, x:pKeys, y:ys,\n               marker:{{color:LOC_COLORS[loc]||'#aaa'}},\n               hovertemplate:'%{{x}}: %{{y:,.4f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('l-heat', heatTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',\n        title:{{text:cat+' by Process & Country',font:{{size:11,color:'#1F3864'}}}},\n        xaxis:Object.assign({{}},DARK.xaxis,{{tickangle:-35}})}})\n      , PLOTLY_CONF);\n\n  }} else {{\n    // Time-series per country\n    const allRows = filteredLciaRows(method, cat, null, locs);\n    const procKeys= [...new Set(allRows.map(r=>r.src))].sort();\n\n    // l-proc: time series per process\n    const tByProc = procKeys.map((proc,pi) => {{\n      const ys = PERIODS.map(tp => allRows.filter(r=>r.src===proc&&r.t===tp).reduce((s,r)=>s+r.val,0));\n      return {{type:'scatter',mode:'lines+markers',name:proc,x:PERIODS,y:ys,\n               line:{{color:PROCESS_COLOR[pi%PROCESS_COLOR.length],width:2}},marker:{{size:5}},\n               hovertemplate:'Period %{{x}}: %{{y:,.4f}}<extra>'+proc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('l-proc', tByProc, Object.assign({{}},DARK,{{title:{{text:cat+' by Supply Chain Process Over Time',font:{{size:11,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // l-country: time series per country\n    const tByLoc = locs.map(loc => {{\n      const ys = PERIODS.map(tp => allRows.filter(r=>r.loc===loc&&r.t===tp).reduce((s,r)=>s+r.val,0));\n      return {{type:'scatter',mode:'lines+markers',name:loc,x:PERIODS,y:ys,\n               line:{{color:LOC_COLORS[loc]||'#aaa',width:2}},marker:{{size:5}},\n               hovertemplate:'Period %{{x}}: %{{y:,.4f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('l-country', tByLoc, Object.assign({{}},DARK,{{title:{{text:cat+' by Country Over Time',font:{{size:11,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // Stacked bar over time (total by period)\n    const stkTraces = locs.map(loc => {{\n      const ys = PERIODS.map(tp => allRows.filter(r=>r.loc===loc&&r.t===tp).reduce((s,r)=>s+r.val,0));\n      return {{type:'bar',name:loc,x:PERIODS,y:ys,marker:{{color:LOC_COLORS[loc]||'#aaa'}},\n               hovertemplate:'Period %{{x}}: %{{y:,.4f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('l-pie', stkTraces, Object.assign({{}},DARK,{{barmode:'stack',title:{{text:cat+' Stacked by Country',font:{{size:11,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // Stacked bar — x = process, stacked by country (cumulative across all periods)\n    const allPKeys = [...new Set(allRows.map(r=>r.src))].sort();\n    const tsHeatTraces = locs.map(loc => {{\n      const ys = allPKeys.map(proc => allRows.filter(r=>r.src===proc&&r.loc===loc).reduce((s,r)=>s+r.val,0));\n      return {{type:'bar', name:loc, x:allPKeys, y:ys,\n               marker:{{color:LOC_COLORS[loc]||'#aaa'}},\n               hovertemplate:'%{{x}}: %{{y:,.4f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('l-heat', tsHeatTraces,\n      Object.assign({{}},DARK,{{barmode:'stack',\n        title:{{text:cat+' by Process & Country (cumulative)',font:{{size:11,color:'#1F3864'}}}},\n        xaxis:Object.assign({{}},DARK.xaxis,{{tickangle:-35}})}})\n      , PLOTLY_CONF);\n  }}\n}}\n\n// ── TAB 4: POLLUTANTS ─────────────────────────────────────────────────────────\nfunction setPollMode(m) {{\n  pollMode = m;\n  document.getElementById('p-snap-btn').classList.toggle('active', m==='snapshot');\n  document.getElementById('p-time-btn').classList.toggle('active', m==='timeseries');\n  document.getElementById('pollPeriod').disabled = (m==='timeseries');\n  renderPoll();\n}}\n\nfunction renderPoll() {{\n  const locs    = getActiveLocs('pollChips');\n  const period  = pollMode==='snapshot' ? parseInt(document.getElementById('pollPeriod').value) : null;\n  const topN    = parseInt(document.getElementById('pollTopN').value);\n  const search  = document.getElementById('pollSearch').value.toLowerCase();\n  const selFlow = document.getElementById('pollFlow').value;\n\n  if (!D.pollutant_flows || D.pollutant_flows.length === 0) {{\n    ['p-bar','p-proc','p-country','p-time'].forEach(id => {{\n      document.getElementById(id).innerHTML =\n        '<p style="text-align:center;color:#999;padding:40px;font-size:12px">pollutant_flow.csv not found in data directory.<br>Run aggregate_inventory.py first.</p>';\n    }});\n    return;\n  }}\n\n  // Compute totals by flow key for top-N ranking\n  const flowTotals = D.pollutant_flows\n    .filter(f => !search || f.toLowerCase().includes(search))\n    .map(f => {{\n      const rows = filteredPollRows(f, period, locs);\n      return {{key:f, total:rows.reduce((s,r)=>s+r.val,0)}};\n    }})\n    .sort((a,b)=>b.total-a.total)\n    .slice(0, topN);\n\n  // Always include benzene variants (any name containing 'benz') regardless of rank\n  D.pollutant_flows\n    .filter(f => f.toLowerCase().includes('benz'))\n    .forEach(function(f) {{\n      if (!flowTotals.find(function(x) {{ return x.key === f; }})) {{\n        const bRows = filteredPollRows(f, period, locs);\n        const bTot  = bRows.reduce(function(s,r) {{ return s+r.val; }}, 0);\n        flowTotals.push({{key:f, total:bTot}});\n      }}\n    }});\n\n  // Bar: top substances total\n  const bKeys = flowTotals.map(f=>f.key.length>40?f.key.substring(0,38)+'…':f.key);\n  const bVals = flowTotals.map(f=>f.total);\n  Plotly.react('p-bar', [{{type:'bar',x:bVals,y:bKeys,orientation:'h',\n    marker:{{color:'#00c896',opacity:.8}},\n    hovertemplate:'%{{y}}: %{{x:,.4f}}<extra></extra>'}}],\n    Object.assign({{}},DARK,{{title:{{text:'Top Substances by Total Mass',font:{{size:11,color:'#1F3864'}}}},\n      yaxis:{{automargin:true,tickfont:{{size:8}}}},margin:{{l:200,r:20,t:28,b:50}}}}), PLOTLY_CONF);\n\n  // For selected or top flow: breakdown by process and country\n  const focusKey = selFlow || (flowTotals[0]||{{}}).key;\n  if (focusKey) {{\n    const focusRows = filteredPollRows(focusKey, period, locs);\n\n    // By process\n    const byProc = {{}};\n    focusRows.forEach(r=>{{ byProc[r.src]=(byProc[r.src]||0)+r.val; }});\n    const pKeys = Object.keys(byProc).sort();\n    Plotly.react('p-proc',[{{type:'bar',x:pKeys,y:pKeys.map(k=>byProc[k]),\n      marker:{{color:pKeys.map((_,i)=>PROCESS_COLOR[i%PROCESS_COLOR.length]),opacity:.85}},\n      hovertemplate:'%{{x}}: %{{y:,.4f}}<extra></extra>'}}],\n      Object.assign({{}},DARK,{{title:{{text:(focusKey.length>40?focusKey.substring(0,38)+'…':focusKey)+' by Process',font:{{size:10,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // By country\n    const byLoc = {{}};\n    focusRows.forEach(r=>{{ byLoc[r.loc]=(byLoc[r.loc]||0)+r.val; }});\n    const lKeys = locs.filter(l=>byLoc[l]>0);\n    Plotly.react('p-country',[{{type:'bar',x:lKeys,y:lKeys.map(l=>byLoc[l]),\n      marker:{{color:lKeys.map(l=>LOC_COLORS[l]||'#aaa'),opacity:.85}},\n      hovertemplate:'%{{x}}: %{{y:,.4f}}<extra></extra>'}}],\n      Object.assign({{}},DARK,{{title:{{text:(focusKey.length>40?focusKey.substring(0,38)+'…':focusKey)+' by Country',font:{{size:10,color:'#1F3864'}}}}}}), PLOTLY_CONF);\n\n    // Time series for focus flow\n    const timeTraces = locs.map(loc => {{\n      const ys = PERIODS.map(tp => filteredPollRows(focusKey,tp,[loc]).reduce((s,r)=>s+r.val,0));\n      return {{type:'scatter',mode:'lines+markers',name:loc,x:PERIODS,y:ys,\n               line:{{color:LOC_COLORS[loc]||'#aaa',width:2}},marker:{{size:5}},\n               hovertemplate:'Period %{{x}}: %{{y:,.4f}}<extra>'+loc+'</extra>'}};\n    }}).filter(tr=>tr.y.some(v=>v>0));\n    Plotly.react('p-time', timeTraces,\n      Object.assign({{}},DARK,{{title:{{text:(focusKey.length>40?focusKey.substring(0,38)+'…':focusKey)+' Over Time',font:{{size:10,color:'#1F3864'}}}}}}),\n      PLOTLY_CONF);\n  }}\n}}\n\n// ── Trade table filter ────────────────────────────────────────────────────────\nfunction filterTrade() {{\n  var q    = document.getElementById('tradeFilter').value.toLowerCase();\n  var locF = document.getElementById('tradeLocFrom').value;\n  var locT = document.getElementById('tradeLocTo').value;\n  var per  = document.getElementById('tradePeriod').value;\n  document.querySelectorAll('#tradeTable tbody tr').forEach(function(row) {{\n    var cells = row.cells;\n    var txt   = row.innerText.toLowerCase();\n    var matchQ = !q    || txt.includes(q);\n    var matchF = !locF || (cells[2] && cells[2].innerText.trim() === locF);\n    var matchT = !locT || (cells[4] && cells[4].innerText.trim() === locT);\n    var matchP = !per  || (cells[0] && cells[0].innerText.trim() === per);\n    row.style.display = (matchQ && matchF && matchT && matchP) ? '' : 'none';\n  }});\n}}\n\n// ── All flows filter ──────────────────────────────────────────────────────────\nvar _flowFilter = 'all';\nfunction setFlowFilter(f) {{\n  _flowFilter = f;\n  ['All','Active','Cross','Unused'].forEach(function(x) {{\n    var el = document.getElementById('btn'+x);\n    if (el) el.classList.remove('active');\n  }});\n  var sel = document.getElementById('btn' + f.charAt(0).toUpperCase() + f.slice(1));\n  if (sel) sel.classList.add('active');\n  filterFlows();\n}}\nfunction filterFlows() {{\n  var q   = document.getElementById('flowFilter').value.toLowerCase();\n  var per = document.getElementById('flowPeriod').value;\n  var loc = document.getElementById('flowLoc').value;\n  document.querySelectorAll('#flowTable tbody tr').forEach(function(row) {{\n    var cls   = row.className;\n    var isUnu = cls.includes('unused');\n    var isCrs = cls.includes('cross');\n    var txt   = row.innerText.toLowerCase();\n    var cells = row.cells;\n    var matchQ = !q   || txt.includes(q);\n    var matchP = !per || (cells[0] && cells[0].innerText.trim() === per);\n    var matchL = !loc || txt.includes(loc.toLowerCase());\n    var matchC =\n      _flowFilter === 'all'    ||\n      (_flowFilter === 'active' && !isUnu) ||\n      (_flowFilter === 'cross'  && isCrs)  ||\n      (_flowFilter === 'unused' && isUnu);\n    row.style.display = (matchQ && matchP && matchL && matchC) ? '' : 'none';\n  }});\n}}\n</script>\n</body>\n</html>"""
    with open(path, 'w', encoding='utf-8') as _h:
        _h.write(_g)
    print(f'✅ Dashboard written to {path}')

def main():
    """Entry point — parses CLI args, loads data, computes LCIA and pollutant aggregations, builds datasets, and renders the HTML dashboard.

    :returns: None
    """
    _a = argparse.ArgumentParser(description='Generate BLEECAM analytics dashboard HTML.')
    _a.add_argument('--data', type=Path, default=Path('./data'), help='Directory containing model CSVs (default: ./data)')
    _a.add_argument('--out', type=Path, default=Path('bleecam_dashboard.html'), help='Output HTML path (default: bleecam_dashboard.html)')
    _a.add_argument('--obj-value', type=float, default=0.0)
    _a.add_argument('--obj-name', type=str, default='total_cost_incl_holding')
    _b = _a.parse_args()
    print(f'Loading data from: {_b.data}')
    _c = load_data(_b.data)
    print('Computing LCIA totals...')
    _d = compute_lcia_by_process_location(_c['results'], _c['ef'])
    print('Computing pollutant totals...')
    _e = compute_pollutant_by_process_location(_c['results'], _c['pollutants'])
    print('Building JSON datasets...')
    _f = build_json_datasets(_c['results'], _d, _e, _c['ef'])
    _g = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    render_html(_f, _b.obj_value, _b.obj_name, _g, _b.out)
if __name__ == '__main__':
    main()